/**
 * RateUrProfs Comprehensive Database Deduplication & Integrity Script
 *
 * Safely audits, merges, and enforces uniqueness across:
 * 1. Universities (VJU, test universities, inst-* autogenerated slugs, seed duplicates)
 * 2. Lecturers (OpenAlex author splits, name/institution collisions)
 * 3. Affiliations & Reviews (preserving referential integrity)
 *
 * Usage:
 *   node --env-file=.env.local -r tsx/register scripts/deduplicate_database.ts --dry-run
 *   node --env-file=.env.local -r tsx/register scripts/deduplicate_database.ts --execute
 */

import { Pool } from "pg";
import fs from "node:fs";
import path from "node:path";

interface UniRecord {
  id: string;
  name: string;
  short_name: string;
  english_name: string | null;
  city: string | null;
  region: string | null;
  official_domain: string | null;
  official_website: string | null;
  institution_type: string;
  total_professors: number;
  alternative_names: string | null;
  discovery_source: string;
  verification_status: string;
  rating_average: string | null;
  total_reviews: number;
}

interface MergeGroup {
  canonicalId: string;
  duplicateIds: string[];
  canonicalName: string;
  reason: string;
  aliasesToAdd: string[];
}

function normalizeCore(str: string): string {
  if (!str) return "";
  let s = str
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
  // Strip common Vietnamese university prefix words to compare core institution name
  s = s.replace(/^(?:trường\s+)?(?:đại\s+học|học\s+viện|cao\s+đẳng)\s+/g, "");
  s = s.replace(/[^a-z0-9]/g, "");
  return s;
}

function normalizeStrict(str: string): string {
  if (!str) return "";
  return str
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
}

async function main() {
  const isExecute = process.argv.includes("--execute");
  const isDryRun = !isExecute;

  console.log("==============================================================================");
  console.log(" RATEURPROFS FULL DATABASE DEDUPLICATION & INTEGRITY MIGRATION");
  console.log(` Mode: ${isExecute ? ">>> LIVE EXECUTION (ACID TRANSACTION) <<<" : "DRY RUN (AUDIT ONLY)"}`);
  console.log("==============================================================================\n");

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.error("[-] ERROR: DATABASE_URL is not set.");
    process.exit(1);
  }

  const pool = new Pool({ connectionString: databaseUrl, connectionTimeoutMillis: 10000 });
  const client = await pool.connect();

  try {
    // -------------------------------------------------------------------------
    // STEP 1: PRE-FLIGHT VERIFICATION & TABLE TELEMETRY
    // -------------------------------------------------------------------------
    console.log("[1/6] Inspecting pre-flight database state...");
    const uniCountRes = await client.query("SELECT COUNT(*) FROM universities");
    const lecCountRes = await client.query("SELECT COUNT(*) FROM lecturers");
    const affCountRes = await client.query("SELECT COUNT(*) FROM affiliations");
    const revCountRes = await client.query("SELECT COUNT(*) FROM reviews");
    const schRevCountRes = await client.query("SELECT COUNT(*) FROM school_reviews");

    const initialUniCount = parseInt(uniCountRes.rows[0].count, 10);
    const initialLecCount = parseInt(lecCountRes.rows[0].count, 10);
    const initialAffCount = parseInt(affCountRes.rows[0].count, 10);
    const initialRevCount = parseInt(revCountRes.rows[0].count, 10);
    const initialSchRevCount = parseInt(schRevCountRes.rows[0].count, 10);

    console.log(`    - Universities:    ${initialUniCount}`);
    console.log(`    - Lecturers:       ${initialLecCount}`);
    console.log(`    - Affiliations:    ${initialAffCount}`);
    console.log(`    - Reviews:         ${initialRevCount}`);
    console.log(`    - School Reviews:  ${initialSchRevCount}\n`);

    // Ensure aliases table exists
    await client.query(`
      CREATE TABLE IF NOT EXISTS institution_aliases (
        alias_id VARCHAR(128) PRIMARY KEY,
        canonical_id VARCHAR(64) REFERENCES universities(id) ON DELETE CASCADE,
        alias_name TEXT,
        created_at BIGINT
      );
      CREATE INDEX IF NOT EXISTS idx_inst_aliases_canonical ON institution_aliases(canonical_id);
    `);

    // -------------------------------------------------------------------------
    // STEP 2: IDENTIFY AND PURGE TEST UNIVERSITIES
    // -------------------------------------------------------------------------
    console.log("[2/6] Detecting test & synthetic mock universities...");
    const testUnisRes = await client.query(`
      SELECT id, name FROM universities 
      WHERE id LIKE 'test-uni-%' OR name ILIKE '%Thử nghiệm%'
    `);
    const testUniIds = testUnisRes.rows.map((r) => r.id);
    console.log(`    Found ${testUniIds.length} test universities created by test suites.`);

    // -------------------------------------------------------------------------
    // STEP 3: BUILD DETERMINISTIC UNIVERSITY MERGE GROUPS
    // -------------------------------------------------------------------------
    console.log("[3/6] Analyzing university duplicate groups...");
    const allUnisRes = await client.query("SELECT * FROM universities");
    const allUnis: UniRecord[] = allUnisRes.rows;
    const uniMap = new Map<string, UniRecord>();
    for (const u of allUnis) {
      uniMap.set(u.id, u);
    }

    const mergeGroups: MergeGroup[] = [];
    const mergedDuplicateIds = new Set<string>();

    // 3.1 Known High-Priority Institution Duplicate Clusters
    const knownClusters: { canonicalId: string; candidates: string[]; reason: string }[] = [
      {
        canonicalId: "vnu-vju",
        candidates: ["viet-nhat", "viet-nhat-2", "inst-truong-dai-hoc-viet-nhat-dai-hoc", "vju"],
        reason: "Vietnam Japan University duplicate records across crawler, seed, and gazette imports",
      },
      {
        canonicalId: "vgu",
        candidates: ["viet-duc", "inst-truong-dai-hoc-viet-duc"],
        reason: "Vietnamese-German University duplicates",
      },
      {
        canonicalId: "vnuhcm",
        candidates: ["quoc-gia-thanh-pho-ho-chi-minh", "inst-dai-hoc-quoc-gia-thanh-pho-ho-ch"],
        reason: "VNU Ho Chi Minh City national university duplicates",
      },
      {
        canonicalId: "ulsa",
        candidates: ["lao-dong-xa-hoi", "lao-dong-xa-hoi-2"],
        reason: "University of Labour and Social Affairs duplicates",
      },
      {
        canonicalId: "phong-khong-khong-quan",
        candidates: ["phong-khong-khong-quan-2", "inst-hoc-vien-phong-khong-khong-quan"],
        reason: "Air Defence - Air Force Academy duplicates",
      },
      {
        canonicalId: "kinh-te-ky-thuat-cong-nghiep",
        candidates: ["kinh-te-ky-thuat-cong-nghiep-2", "inst-truong-dai-hoc-kinh-te-ky-thuat-"],
        reason: "UNETI duplicates",
      },
      {
        canonicalId: "fpt",
        candidates: ["inst-truong-dai-hoc-fpt"],
        reason: "FPT University duplicate generated by HDGSNN",
      },
      {
        canonicalId: "dtu",
        candidates: ["inst-truong-dai-hoc-duy-tan"],
        reason: "Duy Tan University duplicate generated by HDGSNN",
      },
      {
        canonicalId: "hbu",
        candidates: ["hoa-binh", "inst-truong-dai-hoc-hoa-binh"],
        reason: "Hoa Binh University duplicates",
      },
      {
        canonicalId: "vnam",
        candidates: ["am-nhac-quoc-gia-viet-nam"],
        reason: "Vietnam National Academy of Music duplicates",
      },
      {
        canonicalId: "vimaru",
        candidates: ["vmu"],
        reason: "Vietnam Maritime University duplicate abbreviations",
      },
      {
        canonicalId: "hcmulaw",
        candidates: ["ulaw"],
        reason: "Ho Chi Minh City University of Law duplicate abbreviations",
      },
      {
        canonicalId: "hcmuaf",
        candidates: ["nlu"],
        reason: "Nong Lam University duplicate abbreviations",
      },
      {
        canonicalId: "ttn",
        candidates: ["ttu"],
        reason: "Tay Nguyen University duplicate abbreviations",
      },
      {
        canonicalId: "tnut",
        candidates: ["tnu-tnut"],
        reason: "Thai Nguyen University of Technology duplicate abbreviations",
      },
      {
        canonicalId: "humg",
        candidates: ["mo-dia-chat"],
        reason: "Hanoi University of Mining and Geology duplicates",
      },
      {
        canonicalId: "neu",
        candidates: ["inst-truong-dai-hoc-kinh-te-quoc-dan"],
        reason: "National Economics University HDGSNN duplicate",
      },
      {
        canonicalId: "ftu",
        candidates: ["inst-truong-dai-hoc-ngoai-thuong"],
        reason: "Foreign Trade University HDGSNN duplicate",
      },
      {
        canonicalId: "hust",
        candidates: ["inst-dai-hoc-bach-khoa-ha-noi"],
        reason: "HUST HDGSNN duplicate",
      },
      {
        canonicalId: "hcmut",
        candidates: ["inst-truong-dai-hoc-bach-khoa-dai-hoc-"],
        reason: "HCMUT HDGSNN duplicate",
      },
      {
        canonicalId: "ump",
        candidates: ["inst-dai-hoc-y-duoc-tp-ho-chi-minh"],
        reason: "University of Medicine and Pharmacy at Ho Chi Minh City HDGSNN duplicate",
      },
      {
        canonicalId: "vnu-uet",
        candidates: ["inst-truong-dai-hoc-cong-nghe-dai-hoc"],
        reason: "VNU UET HDGSNN duplicate",
      },
      {
        canonicalId: "vnu-ussh",
        candidates: ["inst-truong-dai-hoc-khoa-hoc-xa-hoi-v"],
        reason: "VNU USSH HDGSNN duplicate",
      },
      {
        canonicalId: "vnu-hus",
        candidates: ["inst-truong-dai-hoc-khoa-hoc-tu-nhien"],
        reason: "VNU HUS HDGSNN duplicate",
      },
      {
        canonicalId: "ajc",
        candidates: ["inst-hoc-vien-bao-chi-va-tuyen-truyen"],
        reason: "Academy of Journalism and Communication HDGSNN duplicate",
      },
      {
        canonicalId: "ptit",
        candidates: ["inst-hoc-vien-cong-nghe-buu-chinh-vien"],
        reason: "PTIT HDGSNN duplicate",
      },
      {
        canonicalId: "hmu",
        candidates: ["inst-truong-dai-hoc-y-ha-noi"],
        reason: "Hanoi Medical University HDGSNN duplicate",
      },
      {
        canonicalId: "ueh",
        candidates: ["inst-dai-hoc-kinh-te-tp-ho-chi-minh"],
        reason: "University of Economics Ho Chi Minh City HDGSNN duplicate",
      },
    ];

    for (const cluster of knownClusters) {
      if (!uniMap.has(cluster.canonicalId)) continue;
      const canonical = uniMap.get(cluster.canonicalId)!;
      const dups: string[] = [];
      const aliases: string[] = [];

      for (const candId of cluster.candidates) {
        if (uniMap.has(candId) && candId !== cluster.canonicalId && !mergedDuplicateIds.has(candId)) {
          dups.push(candId);
          mergedDuplicateIds.add(candId);
          const cand = uniMap.get(candId)!;
          if (cand.name && cand.name !== canonical.name) aliases.push(cand.name);
          if (cand.short_name && cand.short_name !== canonical.short_name) aliases.push(cand.short_name);
        }
      }

      if (dups.length > 0) {
        mergeGroups.push({
          canonicalId: cluster.canonicalId,
          duplicateIds: dups,
          canonicalName: canonical.name,
          reason: cluster.reason,
          aliasesToAdd: aliases,
        });
      }
    }

    // 3.2 Dynamic High-Confidence Grouping by Normalized Core Name
    const normCoreMap = new Map<string, UniRecord[]>();
    for (const u of allUnis) {
      if (testUniIds.includes(u.id) || mergedDuplicateIds.has(u.id)) continue;
      const key = normalizeCore(u.name);
      if (!key) continue;
      if (!normCoreMap.has(key)) normCoreMap.set(key, []);
      normCoreMap.get(key)!.push(u);
    }

    for (const [key, records] of normCoreMap.entries()) {
      if (records.length < 2) continue;

      records.sort((a, b) => {
        const aIsInst = a.id.startsWith("inst-") ? 1 : 0;
        const bIsInst = b.id.startsWith("inst-") ? 1 : 0;
        if (aIsInst !== bIsInst) return aIsInst - bIsInst; // standard slug first

        if ((b.total_professors || 0) !== (a.total_professors || 0)) {
          return (b.total_professors || 0) - (a.total_professors || 0);
        }

        const aHasDomain = a.official_domain && (a.official_domain.endsWith(".edu.vn") || a.official_domain.endsWith(".ac.vn")) && !a.official_domain.includes("-2.") ? 1 : 0;
        const bHasDomain = b.official_domain && (b.official_domain.endsWith(".edu.vn") || b.official_domain.endsWith(".ac.vn")) && !b.official_domain.includes("-2.") ? 1 : 0;
        return bHasDomain - aHasDomain;
      });

      const canonical = records[0];
      const dups = records.slice(1);
      const dupIds: string[] = [];
      const aliases: string[] = [];

      for (const d of dups) {
        if (!mergedDuplicateIds.has(d.id)) {
          dupIds.push(d.id);
          mergedDuplicateIds.add(d.id);
          if (d.name && d.name !== canonical.name) aliases.push(d.name);
          if (d.short_name && d.short_name !== canonical.short_name) aliases.push(d.short_name);
        }
      }

      if (dupIds.length > 0) {
        mergeGroups.push({
          canonicalId: canonical.id,
          duplicateIds: dupIds,
          canonicalName: canonical.name,
          reason: `Normalized core name match: "${key}"`,
          aliasesToAdd: aliases,
        });
      }
    }

    // 3.3 Dynamic High-Confidence Grouping by Official Domain
    const domainMap = new Map<string, UniRecord[]>();
    for (const u of allUnis) {
      if (testUniIds.includes(u.id) || mergedDuplicateIds.has(u.id)) continue;
      if (
        u.official_domain &&
        u.official_domain.includes(".") &&
        !u.official_domain.startsWith("inst-") &&
        !u.official_domain.includes("-2.") &&
        !u.official_domain.includes("test-uni")
      ) {
        const d = u.official_domain.toLowerCase().trim();
        if (!domainMap.has(d)) domainMap.set(d, []);
        domainMap.get(d)!.push(u);
      }
    }

    for (const [dom, records] of domainMap.entries()) {
      if (records.length < 2) continue;
      records.sort((a, b) => (b.total_professors || 0) - (a.total_professors || 0));

      const canonical = records[0];
      const dups = records.slice(1);
      const dupIds: string[] = [];
      const aliases: string[] = [];

      for (const d of dups) {
        if (!mergedDuplicateIds.has(d.id)) {
          dupIds.push(d.id);
          mergedDuplicateIds.add(d.id);
          if (d.name && d.name !== canonical.name) aliases.push(d.name);
          if (d.short_name && d.short_name !== canonical.short_name) aliases.push(d.short_name);
        }
      }

      if (dupIds.length > 0) {
        mergeGroups.push({
          canonicalId: canonical.id,
          duplicateIds: dupIds,
          canonicalName: canonical.name,
          reason: `Exact official domain collision: "${dom}"`,
          aliasesToAdd: aliases,
        });
      }
    }

    const totalDupsToMerge = mergeGroups.reduce((acc, g) => acc + g.duplicateIds.length, 0);
    console.log(`    Identified ${mergeGroups.length} university merge groups encompassing ${totalDupsToMerge} duplicate records.`);

    // -------------------------------------------------------------------------
    // STEP 4: DETECT DUPLICATE LECTURERS (OpenAlex Splits & Collisions)
    // -------------------------------------------------------------------------
    console.log("[4/6] Detecting duplicate lecturers within institutions...");
    const dupLecturersRes = await client.query(`
      SELECT 
        a.university_id,
        l.normalized_name,
        COUNT(*) as cnt,
        array_agg(l.id ORDER BY (CASE WHEN l.rating_count > 0 THEN 1 ELSE 2 END), LENGTH(l.id) ASC, l.created_at ASC) as lecturer_ids
      FROM lecturers l
      JOIN affiliations a ON l.id = a.lecturer_id
      GROUP BY a.university_id, l.normalized_name
      HAVING COUNT(*) > 1
    `);

    const lecturerMergeGroups: { canonicalLecId: string; duplicateLecIds: string[]; uniId: string; name: string }[] = [];
    let totalLecturerDups = 0;

    for (const row of dupLecturersRes.rows) {
      const ids: string[] = row.lecturer_ids;
      if (ids.length < 2) continue;
      const canonicalLecId = ids[0];
      const duplicateLecIds = ids.slice(1);
      lecturerMergeGroups.push({
        canonicalLecId,
        duplicateLecIds,
        uniId: row.university_id,
        name: row.normalized_name,
      });
      totalLecturerDups += duplicateLecIds.length;
    }
    console.log(`    Identified ${lecturerMergeGroups.length} lecturer duplicate groups encompassing ${totalLecturerDups} duplicate profiles.`);

    // -------------------------------------------------------------------------
    // EXECUTION STAGE
    // -------------------------------------------------------------------------
    if (isDryRun) {
      console.log("\n==============================================================================");
      console.log(" DRY RUN SUMMARY (NO MODIFICATIONS WRITTEN)");
      console.log("==============================================================================");
      console.log(` - Test universities to purge:         ${testUniIds.length}`);
      console.log(` - University duplicate groups:        ${mergeGroups.length}`);
      console.log(` - University rows to merge & remove:  ${totalDupsToMerge}`);
      console.log(` - Expected Universities after merge:  ${initialUniCount - testUniIds.length - totalDupsToMerge}`);
      console.log(` - Lecturer duplicate groups:          ${lecturerMergeGroups.length}`);
      console.log(` - Lecturer profiles to consolidate:   ${totalLecturerDups}`);
      console.log("\nRun with '--execute' to perform the transactional deduplication.");
      return;
    }

    // -------------------------------------------------------------------------
    // TRANSACTIONAL DATABASE MUTATION
    // -------------------------------------------------------------------------
    console.log("\n[5/6] Commencing transactional database deduplication...");
    await client.query("BEGIN;");

    // A. Purge test universities
    if (testUniIds.length > 0) {
      console.log(`    Deleting ${testUniIds.length} mock test universities...`);
      await client.query("DELETE FROM universities WHERE id = ANY($1)", [testUniIds]);
    }

    // B. Merge Universities
    console.log(`    Processing ${mergeGroups.length} university merge groups...`);
    let unisProcessed = 0;

    for (const g of mergeGroups) {
      const canonical = uniMap.get(g.canonicalId);
      if (!canonical) continue;

      // 1. Reassign affiliations: avoid duplicate (lecturer_id, university_id)
      for (const dupId of g.duplicateIds) {
        // Record alias in institution_aliases table
        await client.query(
          `INSERT INTO institution_aliases (alias_id, canonical_id, alias_name, created_at)
           VALUES ($1, $2, $3, $4)
           ON CONFLICT (alias_id) DO UPDATE SET canonical_id = EXCLUDED.canonical_id`,
          [dupId, g.canonicalId, uniMap.get(dupId)?.name || dupId, Date.now()]
        );

        // Delete duplicate affiliations if lecturer is already affiliated with canonical university
        await client.query(
          `DELETE FROM affiliations a1
           WHERE a1.university_id = $1
             AND EXISTS (
               SELECT 1 FROM affiliations a2 
               WHERE a2.lecturer_id = a1.lecturer_id 
                 AND a2.university_id = $2
             )`,
          [dupId, g.canonicalId]
        );

        // Update remaining affiliations to canonical university
        await client.query(
          `UPDATE affiliations 
           SET university_id = $1, university_name = $2, university_short_name = $3
           WHERE university_id = $4`,
          [g.canonicalId, canonical.name, canonical.short_name, dupId]
        );

        // Reassign reviews
        await client.query(
          "UPDATE reviews SET university_id = $1 WHERE university_id = $2",
          [g.canonicalId, dupId]
        );

        // Reassign school_reviews
        await client.query(
          "UPDATE school_reviews SET university_id = $1 WHERE university_id = $2",
          [g.canonicalId, dupId]
        );

        // Reassign sources
        await client.query(
          "UPDATE sources SET university_id = $1 WHERE university_id = $2",
          [g.canonicalId, dupId]
        );

        // Delete the duplicate university record
        await client.query("DELETE FROM universities WHERE id = $1", [dupId]);
      }

      // 2. Consolidate aliases onto canonical university record
      let existingAliases: string[] = [];
      if (canonical.alternative_names) {
        try {
          existingAliases = typeof canonical.alternative_names === "string"
            ? JSON.parse(canonical.alternative_names)
            : canonical.alternative_names;
        } catch {
          existingAliases = [];
        }
      }
      const combinedAliases = Array.from(new Set([...existingAliases, ...g.aliasesToAdd]));

      // 3. Recalculate canonical university statistics
      const profCountRes = await client.query(
        "SELECT COUNT(DISTINCT lecturer_id) FROM affiliations WHERE university_id = $1",
        [g.canonicalId]
      );
      const totalProfessors = parseInt(profCountRes.rows[0].count, 10);

      const reviewStatsRes = await client.query(
        `SELECT COUNT(*) as total, AVG(overall_rating) as avg_rating 
         FROM school_reviews 
         WHERE university_id = $1 AND status = 'published'`,
        [g.canonicalId]
      );
      const totalSchoolReviews = parseInt(reviewStatsRes.rows[0].total || "0", 10);
      const avgSchoolRating = reviewStatsRes.rows[0].avg_rating
        ? parseFloat(reviewStatsRes.rows[0].avg_rating).toFixed(2)
        : null;

      await client.query(
        `UPDATE universities 
         SET alternative_names = $1,
             total_professors = $2,
             total_reviews = $3,
             rating_average = $4,
             updated_at = $5
         WHERE id = $6`,
        [
          JSON.stringify(combinedAliases),
          totalProfessors,
          totalSchoolReviews,
          avgSchoolRating,
          Date.now(),
          g.canonicalId,
        ]
      );

      unisProcessed++;
    }
    console.log(`    Successfully merged ${unisProcessed} university clusters.`);

    // C. Merge Lecturer Duplicates
    console.log(`    Processing ${lecturerMergeGroups.length} lecturer duplicate clusters...`);
    let lecsMerged = 0;

    for (const lg of lecturerMergeGroups) {
      const dupIds = lg.duplicateLecIds;
      const canId = lg.canonicalLecId;

      // 1. Reassign reviews pointing to duplicate lecturers to the canonical lecturer
      await client.query(
        "UPDATE reviews SET lecturer_id = $1 WHERE lecturer_id = ANY($2)",
        [canId, dupIds]
      );

      // 2. Reassign reports pointing to duplicate lecturers
      await client.query(
        "UPDATE reports SET professor_id = $1 WHERE professor_id = ANY($2)",
        [canId, dupIds]
      );

      // 3. Consolidate source URLs
      const sourcesRes = await client.query(
        "SELECT source_urls_json FROM lecturers WHERE id = $1 OR id = ANY($2)",
        [canId, dupIds]
      );
      const allUrls = new Set<string>();
      for (const r of sourcesRes.rows) {
        if (!r.source_urls_json) continue;
        try {
          const list = Array.isArray(r.source_urls_json)
            ? r.source_urls_json
            : JSON.parse(r.source_urls_json);
          list.forEach((u: string) => allUrls.add(u));
        } catch {
          // ignore parsing error
        }
      }

      await client.query(
        "UPDATE lecturers SET source_urls_json = $1 WHERE id = $2",
        [JSON.stringify(Array.from(allUrls)), canId]
      );

      // 4. Remove duplicate affiliations
      await client.query(
        "DELETE FROM affiliations WHERE lecturer_id = ANY($1)",
        [dupIds]
      );

      // 5. Delete duplicate lecturer rows
      await client.query(
        "DELETE FROM lecturers WHERE id = ANY($1)",
        [dupIds]
      );

      lecsMerged++;
    }
    console.log(`    Successfully merged ${lecsMerged} lecturer duplicate groups.`);

    // D. Enforce Database Level Uniqueness Constraints
    console.log("    Applying uniqueness constraints and indexes...");
    await client.query(`
      CREATE UNIQUE INDEX IF NOT EXISTS uq_affiliations_lecturer_uni 
      ON affiliations(lecturer_id, university_id);
    `);

    await client.query("COMMIT;");
    console.log("[+] Transaction committed successfully.");

    // -------------------------------------------------------------------------
    // STEP 6: POST-MIGRATION RECONCILIATION & INTEGRITY CHECKS
    // -------------------------------------------------------------------------
    console.log("\n[6/6] Verifying referential integrity and post-cleanup state...");
    const finalUniRes = await client.query("SELECT COUNT(*) FROM universities");
    const finalLecRes = await client.query("SELECT COUNT(*) FROM lecturers");
    const finalAffRes = await client.query("SELECT COUNT(*) FROM affiliations");
    const vjuCheckRes = await client.query(`
      SELECT id, name, short_name, english_name, total_professors 
      FROM universities 
      WHERE name ILIKE '%Việt Nhật%' OR short_name ILIKE '%VJU%' OR english_name ILIKE '%Vietnam Japan%'
    `);
    const orphanedAffRes = await client.query("SELECT COUNT(*) FROM affiliations WHERE university_id NOT IN (SELECT id FROM universities)");
    const orphanedRevRes = await client.query("SELECT COUNT(*) FROM reviews WHERE university_id NOT IN (SELECT id FROM universities)");

    const finalUniCount = parseInt(finalUniRes.rows[0].count, 10);
    const finalLecCount = parseInt(finalLecRes.rows[0].count, 10);
    const finalAffCount = parseInt(finalAffRes.rows[0].count, 10);
    const orphanedAffCount = parseInt(orphanedAffRes.rows[0].count, 10);
    const orphanedRevCount = parseInt(orphanedRevRes.rows[0].count, 10);

    console.log("==============================================================================");
    console.log(" RECONCILIATION AUDIT REPORT");
    console.log("==============================================================================");
    console.log(` Universities:`);
    console.log(`   - Before:                     ${initialUniCount}`);
    console.log(`   - Test records purged:        ${testUniIds.length}`);
    console.log(`   - Duplicates merged:          ${totalDupsToMerge}`);
    console.log(`   - Final Canonical Count:      ${finalUniCount}`);
    console.log(` Lecturers:`);
    console.log(`   - Before:                     ${initialLecCount}`);
    console.log(`   - Duplicates consolidated:    ${totalLecturerDups}`);
    console.log(`   - Final Canonical Count:      ${finalLecCount}`);
    console.log(` Affiliations:`);
    console.log(`   - Final Count:                ${finalAffCount}`);
    console.log(` Integrity Checks:`);
    console.log(`   - Orphaned Affiliations:      ${orphanedAffCount} (must be 0)`);
    console.log(`   - Orphaned Reviews:           ${orphanedRevCount} (must be 0)`);
    console.log(`\n Vietnam Japan University verification:`);
    for (const r of vjuCheckRes.rows) {
      console.log(`   * [${r.id}] ${r.name} (${r.short_name}) - ${r.total_professors} professors`);
    }

    if (orphanedAffCount > 0 || orphanedRevCount > 0) {
      throw new Error("Integrity check failed: orphaned foreign keys detected!");
    }
  } catch (err) {
    await client.query("ROLLBACK;");
    console.error("[-] Migration failed. Transaction rolled back:", err);
    throw err;
  } finally {
    client.release();
    await pool.end();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
